"""Bind one actual large generated control after exact finite static reviews."""
import hashlib
import json
from pathlib import Path

H = Path(__file__).resolve().parent
def pin(name, digest):
    path = H / name
    raw = path.read_bytes()
    assert hashlib.sha256(raw).hexdigest() == digest, name
    return dict(path=str(path.resolve()), bytes=len(raw), sha256=digest)

helper = pin('run_role_aware_large_injected_v3.py', 'b97792ab1c8a60167947943d482b11f164f335a72abaee4463138edc8710afc3')
evidence = {
    'static_peer': pin('ROLE-AWARE-LARGE-INJECTED-INDEPENDENT-STATIC-REVIEW-v3.json', '913566e18dc2ba118b2ca2aceffeb2cf039991790ccb607868694b228a64db26'),
    'allocation_peer': pin('ROLE-AWARE-LARGE-INJECTED-INDEPENDENT-ALLOCATION-REVIEW-v3.json', 'c7184b5554555a64d7315b0bd607646d4e82f56268045a1bcf13539065d50f10'),
    'code_freeze': pin('ROLE-AWARE-LARGE-CODE-FREEZE-v3.json', '35bc6bf182f0457f10d26ce49b53486e4ea6a5456155fce552dab5f0b28df8cf'),
    'protocol': pin('ROLE-AWARE-LARGE-CODE-PROTOCOL-v3.json', 'be3cdcec599a5f15f2ce029c53caea4f3941230d12693bba24b9b722f60e3e7d'),
    'raw_sidecar_format': pin('ROLE-AWARE-LARGE-RAW-SIDECAR-FORMAT-v1.json', '62fb60c268e2fc4c31bbed43c1c29f0fb7d71468b69d9f991bc78a338bb305e9'),
    'harness_only_check': pin('ROLE-AWARE-LARGE-HARNESS-RAW-SIDECAR-CHECK-v3.json', 'deccd3d3089c71bf485de98936eb5ecb51732e124d17e11d00f00d0cfee1b944'),
    'reference_root_check': pin('ROLE-AWARE-LARGE-REFERENCE-ROOT-CHECK-v1.json', '5f557e17bc4611ed1025ae6ee37964373301f247c87f3323a0ab1d4eafae46a5'),
    'small_gate': pin('ROLE-AWARE-PRODUCER-SMALL-GATE-ACCEPTANCE-v4.json', '096f5781b0c5d92208fcbd6a0da21528939f668be62ccd573c433ae7517b7445'),
}
native = json.loads(Path(evidence['static_peer']['path']).read_bytes())
allocation = json.loads(Path(evidence['allocation_peer']['path']).read_bytes())
assert native['status'] == 'CLEAR_STATIC_CODE_PREPARATION_ONLY' and native['material_blockers'] == []
assert allocation['status'] == 'CLEAR_FINITE_LARGE_INJECTED_PREPARATION_ROOT_EXECUTION_SEPARATE'
pause_pin = pin('ROLE-AWARE-PRODUCER-SOURCE-PAUSE-v4.json', 'a746e552d5fb6a2eef7c80d5a593a9f4a5a606456d4fae63acfb8905cb14e929')
pause = json.loads(Path(pause_pin['path']).read_bytes())
for p in pause['sources'].values():
    raw = Path(p['path']).read_bytes()
    assert len(raw) == p['bytes'] and hashlib.sha256(raw).hexdigest() == p['sha256']
ref_pin = pin('ROLE-AWARE-LARGE-REFERENCE-PROOF-v1.json', '1a3e47ec28b1f96c4ac0d5c9c9eb7c2f13288cf5a6df4e3c4f6853d07a56aa03')
assert json.loads(Path(ref_pin['path']).read_bytes())['status'] == 'REFERENCE_COMPLETE'
scope = dict(schema_version=1, status='ROOT_AUTHORIZED_ONE_LARGE_GENERATED_INJECTED_RUN',
    actual_helper=helper, required_evidence=evidence, source_pause=pause_pin, reference=ref_pin,
    decision='Both exact static peers are clear. The detached raw-retention check passed. Authorize one first actual216-file Source4 control using the pinned reference, source map and helperV3. No earlier actual large producer attempt exists.',
    geometry=dict(N=216,B=2,M=2,Q=8799,R=12255,C=13551,E=1496,generated_input_bytes=9017363601,captured_bytes=209,expected_reads=8799,expected_calls_candidate=9879,expected_calls_terminal=10095,expected_close_attempts=216),
    clock='One captured real helper-main entry sample becomes actual owner start once; every later sample is real monotonic. Work295/hard300 includes metadata/source bootstrap, all producer work, full consumers, cleanup and final veto. Cooperative only; no hard callback-free hang bound or production first-entry qualification.',
    first_result='Exclusive attempt, proof and evidence directory. Retain first genuine terminal or explicitly unissued state, first exception and partial artifacts. No time-selection rerun, source repair, re-freeze, owner/clock reset or retry.',
    persistence='After the source stack unwinds, trusted harness writes exact generated bytes, compact spy log, all existing canonical raw rows/query captures and callback/close facts. Separate elapsed/output bytes. This is experiment evidence persistence, not producer physical I/O or a new source publication ACK.',
    memory='Same1MiB source buffer; only209B original content captured. No bulk body, full call dictionary list, duplicate expected query pool or payload hex. JSONL4096B/row and55,504,896B/file are trusted output bounds, not live memory/RSS or256MiB fit.',
    not_authorized=['real original/protected payload access','SDK/ctypes/Win32/compiler/native/model execution','new84 runtime','physical producer writer/readback','full actual roster admission','application/default changes','downloads or paid calls'],
    qualifications={k:False for k in ('real_entry','real_FFI','physical_IO','full_real_roster','new84_runtime','resource_fit','scientific')},provider_spend_usd=0)
scope_path = H / 'ROLE-AWARE-LARGE-INJECTED-EXECUTION-SCOPE-v3.json'
binding_path = H / 'ROLE-AWARE-LARGE-INJECTED-BINDING-v3.json'
for name in ('ROLE-AWARE-LARGE-INJECTED-ATTEMPT-v3.json','ROLE-AWARE-LARGE-INJECTED-PROOF-v3.json','large-injected-evidence-v3'):
    assert not (H / name).exists(), name
with scope_path.open('x', encoding='utf-8', newline='\n') as out:
    json.dump(scope, out, sort_keys=True, indent=2); out.write('\n')
binding = dict(schema_version=1,mode='GENUINE_LARGE216_INJECTED_FIRST_V3',
    execution_scope=pin(scope_path.name, hashlib.sha256(scope_path.read_bytes()).hexdigest()),
    reference=ref_pin,source_pause=pause_pin,source_map=pause['sources'],helper=helper,
    adapter=pin('role_aware_legacy_fixture_adapter_v2.py','b0f8cbf326f05c9b868b26fbac2eaee5bdd9ae78fdcc15d1da848d2822abff4f'),
    required_evidence=evidence)
with binding_path.open('x', encoding='utf-8', newline='\n') as out:
    json.dump(binding, out, sort_keys=True, indent=2); out.write('\n')
print(json.dumps(dict(scope_sha256=hashlib.sha256(scope_path.read_bytes()).hexdigest(),binding_sha256=hashlib.sha256(binding_path.read_bytes()).hexdigest())))
